const beltExtraDefinitions=[{id:'belt',num:'29',name:'베이스–허리 타이밍벨트 구동안',qty:1,status:'치형 풀리 관찰 / 전달계 가설',reason:'사용자 표시 사진의 두 치형 풀리와 후방 치형 영역을 반영합니다. 수평 벨트의 기초 요 구동안을 적용하고 같은 J5를 최하단으로 옮겼습니다. 모터·아이들러의 역할과 출력 연결은 추정입니다.',note:'5 mm 피치·36:120·폭15·중공 출력 지지·장력 슬롯은 후보입니다. 5축을 유지하며 벨트 치강도·피로·실물 간섭은 미검증입니다.'}];
function beltCircles(c=beltDesign,offset=0){const radius=n=>n*c.pitch/(2*Math.PI);return[{id:'output',x:0,y:0,r:radius(c.outputTeeth),teeth:c.outputTeeth},{id:'drive',x:c.centerX,y:-c.centerY,r:radius(c.driveTeeth),teeth:c.driveTeeth},{id:'idler',x:c.centerX+offset,y:c.centerY,r:radius(c.idlerTeeth),teeth:c.idlerTeeth}];}
function beltRoute(c=beltDesign,offset=0,samples=180){const circles=beltCircles(c,offset),points=circles.flatMap(a=>Array.from({length:samples},(_,i)=>[a.x+a.r*Math.cos(i*2*Math.PI/samples),a.y+a.r*Math.sin(i*2*Math.PI/samples)])),path=convexHull(points);let length=0;const wrap=Object.fromEntries(circles.map(a=>[a.id,0]));for(let i=0;i<path.length;i++){const p=path[i],q=path[(i+1)%path.length];length+=Math.hypot(q[0]-p[0],q[1]-p[1]);for(const a of circles)if(Math.abs(Math.hypot(p[0]-a.x,p[1]-a.y)-a.r)<1e-5&&Math.abs(Math.hypot(q[0]-a.x,q[1]-a.y)-a.r)<1e-5)wrap[a.id]+=2*Math.asin(Math.min(1,Math.hypot(q[0]-p[0],q[1]-p[1])/(2*a.r)));}return{circles,path,length,wrap};}
let beltRouteCache=null;
function beltAnalysis(c=beltDesign){const key=JSON.stringify(c);if(beltRouteCache?.key===key)return beltRouteCache.value;const initial=beltRoute(c),beltTeeth=Math.round(initial.length/c.pitch),nominalLength=beltTeeth*c.pitch,loRoute=beltRoute(c,-6),hiRoute=beltRoute(c,6),takeupPossible=nominalLength>=loRoute.length&&nominalLength<=hiRoute.length;let lo=-6,hi=6;if(takeupPossible)for(let i=0;i<30;i++){const mid=(lo+hi)/2;if(beltRoute(c,mid).length<nominalLength)lo=mid;else hi=mid;}const idlerOffset=takeupPossible?(lo+hi)/2:0,route=beltRoute(c,idlerOffset),ratio=c.outputTeeth/c.driveTeeth,designTorque=c.outputTorque*c.factor,radius=route.circles[0].r/1000,difference=designTorque/radius,tight=c.pretension+difference/2,slack=c.pretension-difference/2,shaftStress=16*designTorque*1000/(Math.PI*c.shaft**3),radialBound=2*c.pretension,bending=32*radialBound*c.shaftSpan/(Math.PI*c.shaft**3),combined=Math.hypot(bending,Math.sqrt(3)*shaftStress),value={...route,ratio,beltTeeth,nominalLength,idlerOffset,takeupPossible,lengthError:route.length-nominalLength,designTorque,difference,tight,slack,radialBound,shaftStress,bending,combined,inputTorque:designTorque/(ratio*c.efficiency),motorTorque:designTorque/(ratio*c.efficiency*c.upstreamRatio*c.upstreamEfficiency),driveWrap:route.wrap.drive*180/Math.PI,engagedDriveTeeth:route.wrap.drive/(2*Math.PI)*c.driveTeeth,outputDiameter:radius*2000,positiveSlack:slack>0};beltRouteCache={key,value};return value;}
