function beltBayClearances(angle=mechanism.angles[4]){if(!beltDesign.enabled||typeof cameraOBBGap!=='function')return[];const rz=mRot('z',angle),moving=[cameraOBB(beltDesign.revisedMount?mTrans(0,0,250):mMul(mTrans(0,0,250),rz),[0,0,0],beltDesign.revisedMount?[200,200,20]:[240,220,20],beltDesign.revisedMount?'Ø200 기초판 포락':'초기 사각 기초판'),...[-1,1].map(s=>cameraOBB(mMul(mTrans(0,0,mechanism.z0),rz),[0,s*91,-42],[beltDesign.revisedMount?140:150,14,142],'J1 지지판')),cameraOBB(mMul(mTrans(0,0,mechanism.z0),rz),[0,-97,0],[105,22,105],'J1 모터 공간'),...[-1,1].map(side=>cameraOBB(mMul(mTrans(0,0,mechanism.z0),rz),[0,side*81,0],[150,12,150],'J1 출력 플랜지'))];return[-1,1].filter(side=>batteryDesign.installed[side>0?0:1]).map(side=>{const bay=cameraOBB(mIdentity(),[batteryDesign.x,side*batteryDesign.y,batteryDesign.z],batteryDesign.size,'팩 예약'),pair=moving.map(part=>({part:part.name,gap:cameraOBBGap(part,bay)})).reduce((a,b)=>a.gap<b.gap?a:b);return{side,...pair};});}
